use std::fs;
use std::io::Write;
use std::path::Path;
use anyhow::{Result, Context};

const PRE_COMMIT_HOOK: &str = r#"#!/bin/sh
# Xi pre-commit hook
# Auto-generated by `xi install-hooks --pre-commit`
# Do not edit manually; use `xi install-hooks --uninstall` to remove.

xi selfcheck
"#;

const PRE_PUSH_HOOK: &str = r#"#!/bin/sh
# Xi pre-push hook
# Auto-generated by `xi install-hooks --pre-push`
# Do not edit manually; use `xi install-hooks --uninstall` to remove.

xi selfcheck
"#;

/// 安装或卸载 Git 钩子
///
/// - `pre_commit`: 是否安装 pre-commit 钩子
/// - `pre_push`: 是否安装 pre-push 钩子
/// - `uninstall`: 是否卸载钩子（移除由 xi 生成的钩子）
/// - `repo_dir`: 仓库根目录（包含 .git 目录）
pub fn install_hooks(pre_commit: bool, pre_push: bool, uninstall: bool, repo_dir: &Path) -> Result<()> {
    let git_dir = repo_dir.join(".git");
    if !git_dir.exists() {
        anyhow::bail!("当前目录不是 Git 仓库: {}", repo_dir.display());
    }

    let hooks_dir = git_dir.join("hooks");
    fs::create_dir_all(&hooks_dir).context("创建 .git/hooks 目录失败")?;

    if uninstall {
        uninstall_hook(&hooks_dir, "pre-commit")?;
        uninstall_hook(&hooks_dir, "pre-push")?;
        println!("已卸载 Xi Git 钩子");
        return Ok(());
    }

    if pre_commit {
        install_hook(&hooks_dir, "pre-commit", PRE_COMMIT_HOOK)?;
        println!("已安装 pre-commit 钩子");
    }

    if pre_push {
        install_hook(&hooks_dir, "pre-push", PRE_PUSH_HOOK)?;
        println!("已安装 pre-push 钩子");
    }

    if !pre_commit && !pre_push {
        anyhow::bail!("请指定 --pre-commit、--pre-push 或 --uninstall");
    }

    Ok(())
}

fn install_hook(hooks_dir: &Path, name: &str, content: &str) -> Result<()> {
    let hook_path = hooks_dir.join(name);
    
    // 检查是否已存在 xi 生成的钩子
    if hook_path.exists() {
        let existing = fs::read_to_string(&hook_path).context("读取现有钩子失败")?;
        if existing.contains("Xi") && existing.contains("Auto-generated") {
            // 已存在 xi 钩子，覆盖以保持幂等
            write_hook(&hook_path, content)?;
            return Ok(());
        } else {
            // 存在用户自定义钩子，备份后再写入
            let backup_path = hooks_dir.join(format!("{}.xi.backup", name));
            fs::copy(&hook_path, &backup_path).context("备份现有钩子失败")?;
            println!("检测到现有 {} 钩子，已备份至 {}", name, backup_path.display());
            write_hook(&hook_path, content)?;
            return Ok(());
        }
    }

    write_hook(&hook_path, content)?;
    Ok(())
}

fn write_hook(hook_path: &Path, content: &str) -> Result<()> {
    let mut file = fs::File::create(hook_path).context("创建钩子文件失败")?;
    file.write_all(content.as_bytes()).context("写入钩子内容失败")?;
    file.flush().context("刷新钩子文件失败")?;
    
    // 设置可执行权限 (Unix)
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut perms = fs::metadata(hook_path)?.permissions();
        perms.set_mode(0o755);
        fs::set_permissions(hook_path, perms).context("设置钩子可执行权限失败")?;
    }
    Ok(())
}

fn uninstall_hook(hooks_dir: &Path, name: &str) -> Result<()> {
    let hook_path = hooks_dir.join(name);
    
    if !hook_path.exists() {
        return Ok(());
    }

    let content = fs::read_to_string(&hook_path).context("读取钩子内容失败")?;
    
    if content.contains("Xi") && content.contains("Auto-generated") {
        // 是 xi 生成的钩子，直接删除
        fs::remove_file(&hook_path).context("删除钩子失败")?;
        
        // 尝试恢复备份
        let backup_path = hooks_dir.join(format!("{}.xi.backup", name));
        if backup_path.exists() {
            fs::rename(&backup_path, &hook_path).context("恢复备份钩子失败")?;
            println!("已恢复原有 {} 钩子", name);
        }
    } else {
        // 不是 xi 生成的，不处理
        println!("跳过非 Xi 生成的 {} 钩子", name);
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::process::Command;
    use tempfile::tempdir;

    fn init_git_repo(dir: &Path) -> Result<()> {
        Command::new("git")
            .args(["init"])
            .current_dir(dir)
            .output()?;
        Command::new("git")
            .args(["config", "user.email", "test@example.com"])
            .current_dir(dir)
            .output()?;
        Command::new("git")
            .args(["config", "user.name", "Test User"])
            .current_dir(dir)
            .output()?;
        Ok(())
    }

    #[test]
    fn test_install_pre_commit_hook() -> Result<()> {
        let dir = tempdir()?;
        init_git_repo(dir.path())?;
        
        install_hooks(true, false, false, dir.path())?;
        
        let hook_path = dir.path().join(".git/hooks/pre-commit");
        assert!(hook_path.exists(), "pre-commit hook should exist");
        
        let content = fs::read_to_string(&hook_path)?;
        assert!(content.contains("Xi"));
        assert!(content.contains("xi selfcheck"));
        
        // 验证可执行权限
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let perms = fs::metadata(&hook_path)?.permissions();
            assert_eq!(perms.mode() & 0o777, 0o755);
        }
        
        Ok(())
    }

    #[test]
    fn test_install_pre_push_hook() -> Result<()> {
        let dir = tempdir()?;
        init_git_repo(dir.path())?;
        
        install_hooks(false, true, false, dir.path())?;
        
        let hook_path = dir.path().join(".git/hooks/pre-push");
        assert!(hook_path.exists(), "pre-push hook should exist");
        
        let content = fs::read_to_string(&hook_path)?;
        assert!(content.contains("Xi"));
        assert!(content.contains("xi selfcheck"));
        
        Ok(())
    }

    #[test]
    fn test_install_both_hooks() -> Result<()> {
        let dir = tempdir()?;
        init_git_repo(dir.path())?;
        
        install_hooks(true, true, false, dir.path())?;
        
        assert!(dir.path().join(".git/hooks/pre-commit").exists());
        assert!(dir.path().join(".git/hooks/pre-push").exists());
        
        Ok(())
    }

    #[test]
    fn test_uninstall_hooks() -> Result<()> {
        let dir = tempdir()?;
        init_git_repo(dir.path())?;
        
        // 先安装
        install_hooks(true, true, false, dir.path())?;
        assert!(dir.path().join(".git/hooks/pre-commit").exists());
        assert!(dir.path().join(".git/hooks/pre-push").exists());
        
        // 卸载
        install_hooks(false, false, true, dir.path())?;
        
        assert!(!dir.path().join(".git/hooks/pre-commit").exists());
        assert!(!dir.path().join(".git/hooks/pre-push").exists());
        
        Ok(())
    }

    #[test]
    fn test_idempotent_install() -> Result<()> {
        let dir = tempdir()?;
        init_git_repo(dir.path())?;
        
        // 安装两次
        install_hooks(true, false, false, dir.path())?;
        install_hooks(true, false, false, dir.path())?;
        
        let hook_path = dir.path().join(".git/hooks/pre-commit");
        assert!(hook_path.exists());
        
        let content = fs::read_to_string(&hook_path)?;
        // 应该只有一份内容，没有重复
        let count = content.matches("xi selfcheck").count();
        assert_eq!(count, 1);
        
        Ok(())
    }

    #[test]
    fn test_backup_existing_hook() -> Result<()> {
        let dir = tempdir()?;
        init_git_repo(dir.path())?;
        
        // 先创建一个用户自定义的 pre-commit
        let hook_path = dir.path().join(".git/hooks/pre-commit");
        fs::write(&hook_path, "#!/bin/sh
echo 'custom hook'
")?;
        
        // 安装 xi hook
        install_hooks(true, false, false, dir.path())?;
        
        // 验证备份存在
        let backup_path = dir.path().join(".git/hooks/pre-commit.xi.backup");
        assert!(backup_path.exists(), "backup should exist");
        
        let backup_content = fs::read_to_string(&backup_path)?;
        assert_eq!(backup_content, "#!/bin/sh
echo 'custom hook'
");
        
        // 验证当前 hook 是 xi 的
        let current_content = fs::read_to_string(&hook_path)?;
        assert!(current_content.contains("xi selfcheck"));
        
        Ok(())
    }

    #[test]
    fn test_restore_backup_on_uninstall() -> Result<()> {
        let dir = tempdir()?;
        init_git_repo(dir.path())?;
        
        // 创建用户自定义 hook
        let hook_path = dir.path().join(".git/hooks/pre-commit");
        fs::write(&hook_path, "#!/bin/sh
echo 'custom hook'
")?;
        
        // 安装 xi hook (会备份)
        install_hooks(true, false, false, dir.path())?;
        
        // 卸载 (应该恢复备份)
        install_hooks(false, false, true, dir.path())?;
        
        // 验证原有 hook 被恢复
        assert!(hook_path.exists());
        let content = fs::read_to_string(&hook_path)?;
        assert_eq!(content, "#!/bin/sh
echo 'custom hook'
");
        
        Ok(())
    }

    #[test]
    fn test_not_git_repo() -> Result<()> {
        let dir = tempdir()?;
        // 不初始化 git
        
        let result = install_hooks(true, false, false, dir.path());
        assert!(result.is_err());
        assert!(result.unwrap_err().to_string().contains("不是 Git 仓库"));
        
        Ok(())
    }

    #[test]
    fn test_hook_execution() -> Result<()> {
        let dir = tempdir()?;
        init_git_repo(dir.path())?;
        
        install_hooks(true, false, false, dir.path())?;
        
        // 创建一个测试文件并尝试提交（会触发 pre-commit）
        let test_file = dir.path().join("test.txt");
        fs::write(&test_file, "test")?;
        
        Command::new("git")
            .args(["add", "test.txt"])
            .current_dir(dir.path())
            .output()?;
        
        // 运行 pre-commit hook (应该运行 xi selfcheck)
        // 注意：这里只是验证 hook 文件存在且可执行，实际执行需要 xi 在 PATH 中
        let hook_path = dir.path().join(".git/hooks/pre-commit");
        assert!(hook_path.exists());
        
        Ok(())
    }
}
